import math

def reduce_ratio(a: int, b: int) -> int:
    """gcd by repeated subtraction."""
    a = abs(a)
    b = abs(b)
    if a == 0:
        return b
    if b == 0:
        return a
    while a != b:
        if a > b:
            a = a - b
        else:
            b = b - a
    return a

